namespace source=r3d::game::originalrace::source;namespace phys=r3d::physics;
float value(unsigned u){float f;std::memcpy(&f,&u,4);return f;} unsigned word(float f){unsigned u;std::memcpy(&u,&f,4);return u;}
int main(int argc,char**argv){try{if(argc<2 || argc>3)return 2;const bool raw=false;std::ofstream out(argv[1]);const float maximum=value(1057360530U);const float bases[]={-15.F,-3.7F,-1.F,-.999F,0.F,.999F,1.F,3.7F,15.F},inputs[]={-1,-.5F,0,.5F,1};unsigned id=0;
for(float base:bases)for(float input:inputs){phys::WorldDescription desc;desc.gravity=0;desc.includeDeathPlane=false;desc.startPosition={0,0,5};auto& v=desc.vehicle;v.mass=1000;v.halfExtents={1,1,.25F};v.bodyLinearDamping=v.bodyAngularDamping=0;v.wheelContactsEnabled=true;v.maximumTorque=v.restBrakeTorque=v.brakeTorque=0;v.differentialRatio=3.42F;v.maximumRpm=7000;v.idlingRpm=1000;v.steerAngle=maximum;
std::vector<source::GameCar::WheelDynamics> dynamics;for(int i=0;i<4;++i){phys::WheelDescription w;w.position={i<2?1.F:-1.F,i%2?1.F:-1.F,-.5F};w.radius=.5F;w.width=.2F;w.suspensionTravel=.4F;w.inverseMass=1;w.flags=64;w.driven=w.steering=i<2;v.wheels.push_back(w);source::GameCar::WheelDynamics d;d.positionX=w.position.x;d.driven=w.driven;d.steering=w.steering;d.radius=w.radius;dynamics.push_back(d);}
phys::TriangleMesh floor;floor.vertices={{-500,-500,4},{500,-500,4},{500,500,4},{-500,500,4}};floor.indices={0,1,2,0,2,3};desc.collisionMeshes.push_back(floor);std::string error;auto world=phys::createOriginalVehicleWorld(desc,error);if(!world)throw std::runtime_error(error);source::GameCar car;source::GameCar::MotorDescription motor;motor.maximumTorque=motor.brakeTorque=motor.restBrakeTorque=0;car.ConfigureMotor(motor);source::GameCar::DynamicsDescription dyn;dyn.maximumSteerAngle=maximum;dyn.steerRotation=value(1078530011U);car.BindWheels(std::vector<bool>(4,false),std::vector<bool>(4,false));car.ConfigureDynamics(dyn,dynamics);bool seed=true;
world->setVehicleFixedStepController([&](std::size_t,float dt,const phys::VehicleInput&,const phys::VehicleFixedStepState& physical){phys::VehicleDriveCommand result;result.applyAngularStabilization=false;if(seed){return result;}source::GameCar::FixedStepInput in;in.manualSteering=true;in.steering=input;source::GameCar::FixedStepState state;state.signedSpeed=physical.signedSpeed;state.absoluteSpeed=physical.absoluteSpeed;state.horizontalSpeed=physical.horizontalSpeed;state.anyWheelContact=physical.anyWheelContact;state.drivenWheelContact=physical.drivenWheelContact;state.firstDrivenWheelContact=physical.firstDrivenWheelContact;state.allWheelContact=physical.allWheelContact;auto cmd=car.OnFixedStepDrive(dt,in,state);result.preservePhysicalWheelSteering=raw?false:cmd.preservePhysicalWheelSteering;result.steeringAngle=cmd.steeringAngle;result.steeringYaw=cmd.steeringYaw;result.rearWheelX=cmd.rearWheelX;out<<"{\"event\":\"steering.command\",\"case\":"<<id<<",\"base_input_word\":"<<word(base)<<",\"input_word\":"<<word(input)<<",\"visual_word\":"<<word(cmd.steeringAngle)<<",\"physical_speed_word\":"<<word(physical.signedSpeed)<<",\"all_wheels_contact\":"<<(physical.allWheelContact?"true":"false")<<",\"any_wheel_contact\":"<<(physical.anyWheelContact?"true":"false")<<",\"rear_pivot_word\":"<<word(cmd.rearWheelX)<<"}\n";return result;});world->addLinearVelocity(0,{base,0,0});world->step(1.F/60,phys::VehicleInput{});auto before=world->vehicle().body;seed=false;world->step(1.F/60,phys::VehicleInput{});auto after=world->vehicle().body;out<<"{\"event\":\"steering.pose\",\"case\":"<<id<<",\"position_before\":["<<word(before.position.x)<<','<<word(before.position.y)<<','<<word(before.position.z)<<"],\"rotation_before\":["<<word(before.rotation.x)<<','<<word(before.rotation.y)<<','<<word(before.rotation.z)<<','<<word(before.rotation.w)<<"],\"position_after\":["<<word(after.position.x)<<','<<word(after.position.y)<<','<<word(after.position.z)<<"],\"rotation_after\":["<<word(after.rotation.x)<<','<<word(after.rotation.y)<<','<<word(after.rotation.z)<<','<<word(after.rotation.w)<<"]}\n";++id;}
return out.good()?0:4;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 3;}}
